const PERGUNTAS = {
  main: [
    {id:1,type:"multipla",q:"Ao entrar no Magic Kingdom encontramos a Town Square no início da Main Street. Essa praça tem uma estátua homenageando quem?",opts:["Walt Disney e Mickey Mouse","Roy O. Disney e Minnie Mouse","Walt Disney e sua família","Mickey e Minnie Mouse"],ans:1,tip:"A estátua se chama 'Sharing the Magic'. Roy era irmão de Walt e foi quem concluiu a construção do Magic Kingdom após a morte de Walt em 1966.",ind:"🎬 Indicado: Era Uma Vez um Estúdio — Disney+"},
    {id:2,type:"multipla",q:"A Town Square e a Main Street foram inspiradas em qual cidade real?",opts:["Kansas City","Marceline","Chicago","Los Angeles"],ans:1,tip:"Walt Disney passou parte da infância em Marceline, Missouri. A cidade inspirou toda a ambientação da entrada do parque.",ind:"🎵 Indicado: When You Wish Upon a Star — Pinóquio (1940)"},
    {id:3,type:"complete",q:"O único local fixo do Mickey Mouse para encontros e fotos no Magic Kingdom é o ___",words:["The Town Square Theater","City Hall","Main Street Confectionery","Main Street Cinema"],ans:0,tip:"Nas festas de Halloween e Natal o casal Mickey e Minnie aparece junto nesse mesmo local.",ind:"🎬 Indicado: Vapor Willie, Mickey Mouse Curtir — Disney+"},
    {id:4,type:"multipla",q:"Qual restaurante da Town Square é inspirado em um filme clássico da Disney?",opts:["Crystal Palace","Casey's Corner","Tony's Town Square Restaurant","The Plaza Restaurant"],ans:2,tip:"Tony é o cozinheiro italiano dono do restaurante do filme A Dama e o Vagabundo. O famoso espaguete com almôndegas é o prato mais pedido! É um restaurante table-service — reserve com antecedência.",ind:"🎬 Indicado: A Dama e o Vagabundo (1955) · 🎵 Bella Notte"},
    {id:5,type:"multipla",q:"Você sabia que na Town Square do Magic Kingdom existe uma barbearia de verdade chamada Harmony Barber Shop? Quais são os serviços oferecidos?",opts:["Apenas corte infantil e barba","Apenas primeiro corte com certificado","Corte infantil, adulto, primeiro corte e barba","Apenas serviços para crianças"],ans:2,tip:"A Harmony Barber Shop atende crianças e adultos. Primeiro corte de cabelo: acompanha chapéu comemorativo com orelhas do Mickey, mecha de cabelo e certificado oficial de conquista. Funciona com agendamento prévio e gorjeta em dinheiro.",ind:null},
    {id:6,type:"vf",q:"O grupo musical The Dapper Dans se apresenta na Main Street cantando à capela e sapateando.",ans:true,tip:"O quarteto musical passa por toda a Main Street com um estilo dos anos 20 — uma das experiências mais charmosas e gratuitas do parque.",ind:null},
    {id:7,type:"multipla",q:"Qual é a sobremesa mais desejada para comer enquanto assiste ao show Happily Ever After, encontrada na Main Street Confectionery (quick-service)?",opts:["Pipoca personalizada","Algodão doce especial","Sorvete na Pia do Mickey","Maçã decorada da Minnie"],ans:0,tip:"No Brasil personalizamos sorvetes — aqui é a pipoca! Escolha a base (caramelo, manteiga ou kettle), depois a calda e por fim os toppings.",ind:null},
    {id:8,type:"ordenar",q:"Na loja Crystal Arts da Main Street você pode participar da experiência Crystal Wish Keepers. Coloque os passos na ordem correta:",items:["Despeje os cristais no recipiente e faça um pedido especial","Escolha um recipiente de vidro (sapatinho, varinha, rosa da Bela e muitas outras opções)","Um Cast Member selará permanentemente o recipiente com os cristais e o seu sonho","Escolha sua seleção de cores de cristais — cada cor representa um sentimento"],correctOrder:[1,3,0,2],tip:"Uma das experiências mais significativas do parque — cada recipiente carrega um sonho único. É uma experiência paga à parte.",ind:null},
    {id:9,type:"multipla",q:"Na Crystal Arts da Main Street existe uma experiência artística onde artesãos criam peças de cristal únicas ao vivo através do método glass blowing. Qual o nome dessa experiência?",opts:["Hand-Blown Glass Pumpkin","Crystal Glass Magic","Castle Glass Blowing","Glass Slipper Blowing"],ans:0,tip:"Os artesãos criam as peças ao vivo — você assiste tudo sendo feito na hora. Cada peça é única e personalizável! Experiência paga à parte.",ind:null},
    {id:10,type:"multipla",q:"O Mickey Kitchen Sink é uma sobremesa especial do Magic Kingdom. Onde é vendida e o que a torna única?",opts:["No Emporium em uma caixa temática","Na Plaza Ice Cream Parlor (quick-service) em uma miniatura de pia que você leva para casa","No Crystal Palace em um pote do Mickey","Na Main Street Confectionery em uma lata"],ans:1,tip:"A 'pia do Mickey' é uma das sobremesas mais fotografadas da Main Street! A Plaza Ice Cream Parlor é um quick-service.",ind:null},
    {id:11,type:"multipla",q:"Onde fica o pianista que toca músicas Disney em versão clássica no Magic Kingdom?",opts:["The Plaza Restaurant","Main Street Cinema","Casey's Corner","Main Street Confectionery"],ans:2,tip:"Dica de especialista: peça seu hot-dog no Casey's Corner (quick-service) e a sobremesa Pia do Mickey na Plaza Ice Cream Parlor uma hora antes do show de fogos — você garante um dos melhores lugares para assistir!",ind:null},
    {id:12,type:"multipla",q:"O waffle de churros no formato do Mickey é uma sobremesa exclusiva e considerada rara. Onde você pode encontrá-la?",opts:["Nos restaurantes do Magic Kingdom","Apenas nos cruzeiros Disney","Crystal Palace (table-service) no MK, Spyglass Grill no Caribbean Beach Resort e nos cruzeiros Disney","Em todos os parques Disney de Orlando"],ans:2,tip:"Apenas 3 lugares em todo o mundo Disney! Dica de especialista: ao reservar o Crystal Palace para o último horário do café da manhã, você aproveita os itens do almoço pois durante esse horário tem-se a troca do bufê.",ind:null},
    {id:13,type:"multipla",q:"A arquitetura do The Crystal Palace (table-service) se inspirou em qual marco histórico real?",opts:["Na grande estufa real do Jardim Botânico de Versalhes","No Palácio de Cristal de Londres (Crystal Palace, 1851)","Na estação de trem vitoriana de Chicago","No pavilhão de inverno dos czares russos em São Petersburgo"],ans:1,tip:"O visual vitoriano do restaurante é uma homenagem direta ao Crystal Palace de Londres. No restaurante você realiza sua refeição divertida com o Ursinho Pooh e toda a sua turma!",ind:null},
    {id:14,type:"multipla",q:"Por que nenhuma estrutura do Magic Kingdom ultrapassa 61 metros (200 pés) de altura?",opts:["Por causa do limite de peso do solo pantanoso da Flórida","Para a sombra das torres não cobrir as piscinas dos resorts vizinhos","Devido a uma lei da aviação americana que exige luzes vermelhas piscantes acima dessa altura","Para garantir que ventos de furacões não derrubem as torres"],ans:2,tip:"A Disney não queria colocar luzes vermelhas piscando no topo do castelo de conto de fadas! O Castelo tem 57,6m e a Expedition Everest 60,6m — ambos logo abaixo do limite.",ind:null},
    {id:15,type:"multipla",q:"O Magic Kingdom não tem fios elétricos aparentes e o lixo some misteriosamente. Qual estrutura escondida embaixo do parque permite isso?",opts:["Uma rede de metrô subterrâneo para funcionários VIP","Os Utilidors — sistema de túneis térreos onde o parque real foi construído por cima no segundo andar","Um enorme bunker à prova de furacões de titânio","Um lago artificial subterrâneo que gera energia limpa"],ans:1,tip:"O chão que você caminha no Magic Kingdom é na verdade o teto de um enorme complexo de túneis. O lixo é sugado por tubos pneumáticos e as mercadorias chegam sem estragar a magia!",ind:"🎬 Indicado: The Imagineering Story — Disney+"},
    {id:16,type:"multipla",q:"Qual é o segredo de Walt Disney sobre a distância entre cada lixeira no Magic Kingdom?",opts:["Ficam a 100 metros uma da outra","Ficam a no máximo 30 passos de distância — Walt cronometrou quanto tempo uma pessoa andava com lixo antes de jogá-lo no chão","Mudam de lugar com sensores","São pintadas com cor invisível"],ans:1,tip:"Walt observou que a média que alguém aceita caminhar segurando um papel antes de jogá-lo no chão é de 30 passos. Por isso o Magic Kingdom é tão limpo!",ind:null},
    {id:17,type:"vf",q:"A Disney possui uma tecnologia patenteada chamada Smellitizers que libera fragrâncias específicas em momentos precisos através de caixas de ventilação ocultas nos parques e atrações.",ans:true,tip:"Os Smellitizers são dispositivos patenteados que liberam aromas artificiais de forma controlada para criar uma experiência mais imersiva e mágica.",ind:null},
    {id:18,type:"multipla",q:"Qual o cheiro específico da Main Street liberado através da tecnologia Smellitizer?",opts:["Cotton candy — algodão doce","Cookies recém-assados","Pipoca doce","Maçã caramelizada"],ans:1,tip:"A Main Street possui um cheirinho doce de cookies recém-assados. O olfato é o sentido mais conectado às memórias afetivas — esse aroma desperta conforto e felicidade ao entrar no parque!",ind:null},
  ],
  tomorrow: [
    {id:20,type:"multipla",q:"Qual é o conceito temático da Tomorrowland no Magic Kingdom?",opts:["O mundo dos contos de fadas clássicos","Uma visão de futuro segundo Walt Disney","A América do século 18","O mundo da aventura e exploração"],ans:1,tip:"Walt Disney queria mostrar como seria o futuro — tecnologia, espaço e inovação. Uma visão otimista do amanhã que encanta até hoje.",ind:"🎬 Indicado: Tomorrowland (2015) — Disney+"},
    {id:21,type:"multipla",q:"Qual atração da Tomorrowland foi inaugurada no mesmo dia da abertura do Magic Kingdom em 1971?",opts:["Space Mountain","Tomorrowland Speedway","Astro Orbiter","Buzz Lightyear's Space Ranger Spin"],ans:1,tip:"Embora pareça antiga, a Space Mountain só abriu em 1975! A pista de corrida Speedway estava lá desde o dia da inauguração do Magic Kingdom.",ind:null},
    {id:22,type:"multipla",q:"Qual atração da Tomorrowland é ideal para fazer no horário do pôr do sol?",opts:["Space Mountain","TRON","Tomorrowland Transit Authority PeopleMover","Astro Orbiter"],ans:2,tip:"O PeopleMover é um passeio calmo em trilho elevado com vistas panorâmicas deslumbrantes da Tomorrowland. No pôr do sol a vista é ainda mais linda — perfeito para uma pausa sem ficar parado.",ind:null},
    {id:23,type:"multipla",q:"No tranquilo Tomorrowland Transit Authority PeopleMover, qual maquete histórica criada pelo próprio Walt Disney pode ser vista durante o trajeto?",opts:["A maquete original do Castelo da Cinderela","O protótipo arquitetônico original da cidade do EPCOT","A maquete da primeira Disneyland da Califórnia","O protótipo do que seria o Animal Kingdom"],ans:1,tip:"Walt Disney planejou o EPCOT originalmente para ser uma cidade real e futurista. A maquete original pode ser vista de dentro do PeopleMover!",ind:null},
    {id:24,type:"multipla",q:"Qual é a temática principal e a história por trás da atração TRON Lightcycle Run?",opts:["Uma corrida de carros clássicos numa cidade cibernética","Uma viagem espacial para salvar o sistema solar","Uma corrida de Lightcycles do Time Azul contra o Time Laranja no mundo digital conhecido como A Grade (The Grid)","Uma jornada aquática pelos arquivos perdidos do computador central ENCOM"],ans:2,tip:"A premissa da atração é você ser digitalizado para o mundo digital e competir em uma corrida emocionante pelo Time Azul contra a Equipe Laranja — confirmado pelo site oficial D23!",ind:"🎬 Indicado: TRON: O Legado (2010) — Disney+ · 🎵 Trilha do Daft Punk: Derezzed, The Son of Flynn, Adagio for TRON"},
    {id:25,type:"multipla",q:"O que torna o veículo da atração TRON Lightcycle Run único em comparação com as montanhas-russas tradicionais da Disney?",opts:["Os visitantes viajam de pé durante todo o circuito","Os carrinhos possuem assentos giratórios","Os veículos flutuam sobre um trilho magnético","Os visitantes sentam em veículos que imitam motos futuristas, inclinando-se para a frente como em uma motocicleta"],ans:3,tip:"A posição de pilotagem imitando uma moto de corrida (Lightcycle), onde você é preso pelas costas, é o que torna o veículo tão especial e imersivo.",ind:null},
    {id:26,type:"vf",q:"Se um visitante não se sentir confortável na posição de moto da TRON Lightcycle Run ele pode solicitar ao Cast Member um dos carrinhos normais adaptados no final de alguns trens.",ans:true,tip:"A Disney disponibiliza um ou dois carrinhos normais adaptados no final de alguns trens para acessibilidade ou conforto. Informação muito importante para famílias!",ind:null},
    {id:27,type:"vf",q:"Na TRON Lightcycle Run, você precisa guardar sua mochila em um locker gratuito antes de entrar na atração.",ans:true,tip:"É a única atração do Magic Kingdom com essa exigência! Lockers de tamanho médio (30x30x45cm). Itens pequenos como celular e carteira ficam no compartimento embutido abaixo do painel do veículo.",ind:null},
    {id:28,type:"multipla",q:"Por que a TRON Lightcycle Run é mais recomendada à noite do que durante o dia?",opts:["A fila é menor à noite","A transição entre ambiente interno e externo é perfeita à noite — mantendo a ilusão do videogame","A atração só funciona com iluminação noturna","Os efeitos sonoros são mais intensos à noite"],ans:1,tip:"Durante o dia, sair do escuro total para o sol forte da Flórida quebra a ilusão. À noite a transição é contínua e perfeita — uma das experiências mais imersivas de todo o Magic Kingdom!",ind:null},
    {id:29,type:"ordenar",q:"Coloque todas as montanhas-russas do Magic Kingdom em ordem crescente de velocidade:",items:["Space Mountain","Big Thunder Mountain","TRON","The Barnstormer","Seven Dwarfs Mine Train"],correctOrder:[3,0,4,1,2],tip:"Barnstormer (40km/h) → Space Mountain (45km/h) → Seven Dwarfs Mine Train (55km/h) → Big Thunder Mountain (58km/h) → TRON (95-98km/h). O TRON é quase o dobro da velocidade da segunda mais rápida!",ind:null},
    {id:30,type:"multipla",q:"Qual atração da Tomorrowland simula uma viagem pelo espaço sideral no escuro completo com curvas fechadas e quedas surpresa?",opts:["TRON","Astro Orbiter","Space Mountain","PeopleMover"],ans:2,tip:"A Space Mountain não tem looping e a velocidade máxima é de apenas 45km/h — mas o escuro completo e as curvas inesperadas criam uma sensação muito mais intensa do que os números sugerem!",ind:null},
    {id:31,type:"multipla",q:"O que há de especial sobre a disposição dos assentos nos carrinhos da Space Mountain no Magic Kingdom?",opts:["Os visitantes vão sentados de lado","Os assentos são em fila indiana — uma pessoa atrás da outra em fila única","Os carrinhos flutuam com ímãs","Duas pessoas vão no colo uma da outra"],ans:1,tip:"Diferente da versão da Disneyland na Califórnia onde as pessoas vão em duplas lado a lado, em Orlando você vai sozinho em um banco, um atrás do outro.",ind:null},
    {id:32,type:"vf",q:"No Tomorrowland Speedway os visitantes pilotam carrinhos de corrida com volante e acelerador de verdade.",ans:true,tip:"Os carrinhos são movidos a gasolina e atingem no máximo 12km/h! Dica: se um adulto estiver sozinho com duas crianças sem altura mínima, avise o cast member no início da fila — você receberá uma identificação roxa e terá prioridade para a segunda volta sem pegar fila!",ind:null},
    {id:33,type:"multipla",q:"Qual é o objetivo da atração Buzz Lightyear's Space Ranger Spin?",opts:["Salvar a galáxia derrotando o Imperador Zerg com uma arma a laser","Encontrar todos os brinquedos perdidos do Andy","Ajudar o Buzz a voltar para casa","Destruir a nave do Imperador Zurg"],ans:0,tip:"Os veículos giram 360 graus e você mesmo controla a rotação. É uma competição saudável com seu parceiro de nave — quem marca mais pontos acertando os robôs do Zerg vence!",ind:"🎬 Indicado: Saga Toy Story completa — Disney+"},
    {id:34,type:"multipla",q:"Para se tornar um Galactic Hero — pontuação máxima do Buzz Lightyear's Space Ranger Spin — quantos pontos você precisa marcar?",opts:["100.000 pontos","500.000 pontos","999.999 pontos","9.999.999 pontos"],ans:2,tip:"Se você atingir essa pontuação, o painel trava no número máximo. Tire uma foto do painel e mostre aos funcionários na saída para ganhar um adesivo exclusivo de Galactic Hero!",ind:null},
    {id:35,type:"vf",q:"O Monster Inc Laugh Floor é um show interativo com participação do público conduzido pelo Mike Wazowski.",ans:true,tip:"O show é transmitido em telão e o Mike Wazowski interage com o público ao vivo — inclusive pode escolher você para participar! Uma atração divertida e sem filas grandes.",ind:"🎬 Indicado: Monstros S.A. (2001) e Monstros University (2013) — Disney+"},
    {id:36,type:"multipla",q:"Qual é o nome do icônico DJ alienígena animatrônico que comanda o som do restaurante Cosmic Ray's Starlight Café (quick-service)?",opts:["Sonny Eclipse","Stitch","Zurg","Rex"],ans:0,tip:"Ele é um áudio-animatrônico que toca um teclado espacial e faz piadas enquanto os visitantes almoçam. Uma das figuras mais amadas da área.",ind:null},
    {id:37,type:"multipla",q:"Qual é a sobremesa destaque do quiosque Astrofizz (quick-service) na Tomorrowland?",opts:["Sorvete de chocolate com caramelo","Churro coberto com açúcar de cereja, calda de Coca-Cola Cherry e confeitos que estalam na boca","Milkshake de baunilha com calda de menta","Pipoca caramelada com cobertura de chocolate"],ans:1,tip:"O Astrofizz é patrocinado pela Coca-Cola e tem visual futurista. O churro de Cherry Coca com confeitos que estalam na boca é um dos doces mais inusitados do Magic Kingdom!",ind:null},
    {id:38,type:"multipla",q:"O Walt Disney's Carousel of Progress detém um recorde histórico mundial. Qual é ele?",opts:["É a atração com a fila mais longa da história da Disney","É o show com o maior palco móvel do mundo","É a atração que ficou mais tempo em manutenção","É o show de palco com mais apresentações na história do teatro americano"],ans:3,tip:"A atração foi criada pelo próprio Walt Disney para a Feira Mundial de Nova York de 1964. ATENÇÃO: atração fechada para reformas — previsão de reabertura em 2027.",ind:"🎵 Indicado: música 'There's a Great Big Beautiful Tomorrow' — irmãos Sherman"},
  ],
  fantasy: [
    {id:40,type:"multipla",q:"Qual é a temática da Fantasyland no Magic Kingdom?",opts:["O mundo da ficção científica","Os contos de fadas clássicos da Disney","A América colonial","O mundo da aventura e exploração"],ans:1,tip:"A Fantasyland é a área mais querida pelas crianças — onde os contos de fadas clássicos ganham vida. É nessa área que se encontra o Castelo da Cinderela!",ind:"🎬 Indicado: Cinderela (1950) e Cinderela Live Action (2015) — Disney+"},
    {id:41,type:"multipla",q:"Por que o Castelo da Cinderela parece muito mais alto do que seus 57 metros reais quando olhamos da Main Street?",opts:["Por causa da Perspectiva Forçada — janelas e tijolos vão diminuindo de tamanho à medida que o castelo fica mais alto","Porque foi construído em cima de uma colina artificial de 20 metros","Porque o topo é feito de espelhos que refletem as nuvens","Porque as árvores ao redor são podadas para parecerem miniaturas"],ans:0,tip:"Ao diminuir a escala dos tijolos, janelas e torres no topo, o cérebro humano interpreta que o topo está muito mais longe e alto. A engenharia visual favorita da Disney!",ind:null},
    {id:42,type:"multipla",q:"Os mosaicos de vidro dentro do corredor do Castelo da Cinderela usam qual material especial para dar brilho às roupas das irmãs malvadas?",opts:["Ouro real de 14 quilates incorporado nos azulejos","Diamantes falsos colados sobre o vidro","Tinta neon que brilha sob luz negra","Cristais para compor os mosaicos"],ans:0,tip:"Os mosaicos usam pedaços de ouro real e prata junto com mais de 300 mil pedaços de vidro italiano para criar os efeitos de brilho históricos.",ind:null},
    {id:43,type:"vf",q:"O Peter Pan's Flight está aberto desde a inauguração do Magic Kingdom em 1971.",ans:true,tip:"Uma das atrações mais antigas e queridas do parque — aberta desde 1971 e ainda com filas enormes! Um passeio pelos cenários clássicos do Peter Pan que encanta gerações.",ind:"🎬 Indicado: As Aventuras de Peter Pan (1953) e Peter Pan and Wendy (2023) — Disney+"},
    {id:44,type:"multipla",q:"Na fila do Peter Pan's Flight, no berçário da família Darling, quais personagens formam as silhuetas que se movem sozinhas nos brinquedos?",opts:["Wendy, João e Miguel","Capitão Gancho, Sr. Smee e o Crocodilo","Tinker Bell, Peter Pan e os Garotos Perdidos","Nana, a cachorra babá"],ans:0,tip:"As silhuetas dos três irmãos Darling podem ser vistas brincando alegremente nos blocos antes do início da aventura na Terra do Nunca.",ind:null},
    {id:45,type:"multipla",q:"Qual é a tradição entre os fãs Disney na atração It's a Small World?",opts:["Tirar foto com todos os personagens da atração","Jogar uma moedinha de 1 cent e fazer um pedido durante o passeio","Cantar a música da atração do início ao fim","Tocar na água do barco para dar sorte"],ans:1,tip:"Uma tradição encantadora que a maioria dos visitantes não conhece! Guarde uma moedinha de 1 cent antes de entrar na fila.",ind:"🎵 Indicado: música It's a Small World — vai ficar na cabeça por dias!"},
    {id:46,type:"multipla",q:"O estilo visual do It's a Small World — bonecas e cores em tons pastel — foi criado por qual lendária artista da Disney?",opts:["Alice Davis","Harriet Burns","Mary Blair","Marc Davis"],ans:2,tip:"Mary Blair foi brilhante artista conceitual da Disney e Imagineer. Seu estilo modernista e uso de cores vibrantes definiram o design do It's a Small World.",ind:null},
    {id:47,type:"multipla",q:"Quantos cavalos esculpidos à mão existem no Prince Charming Regal Carrousel — o famoso carrossel do parque?",opts:["60 cavalos","72 cavalos","90 cavalos","108 cavalos"],ans:2,tip:"Todos os detalhes em dourado são feitos em folha de ouro 23 quilates, prata e bronze. Para Walt Disney, todo parque deveria ter um carrossel — era o brinquedo onde toda a família consegue se divertir junto.",ind:null},
    {id:48,type:"multipla",q:"O Prince Charming Regal Carrousel tem um cavalo especial considerado pelos fãs como 'cavalo da Cinderela'. Qual detalhe o identifica?",opts:["Ele é o único pintado inteiramente de ouro","Ele é o único com chifres como um unicórnio","Ele tem um laço dourado na cauda e armadura esculpida","Ele tem o nome Cinderela escrito na sela"],ans:2,tip:"O cavalo da Cinderela fica na fileira externa do carrossel com um laço dourado na cauda e flores na crina.",ind:null},
    {id:49,type:"vf",q:"Em frente ao Prince Charming Regal Carrousel qualquer visitante pode tentar retirar a espada Excalibur da bigorna.",ans:true,tip:"É a espada do Rei Arthur do filme A Espada Era a Lei! O mecanismo para levantar a espada é controlado eletronicamente por um funcionário da Disney para criar um momento mágico surpresa!",ind:"🎬 Indicado: A Espada Era a Lei (1963) — Disney+"},
    {id:50,type:"multipla",q:"Dentro da Fantasyland existe um espaço dedicado ao universo da Rapunzel (Enrolados — Tangled). Quantos camaleões amigos do Pascal estão escondidos na praça?",opts:["5 camaleões","8 camaleões","10 camaleões","12 camaleões"],ans:2,tip:"Eles estão camuflados na decoração do parque. Não deixe de verificar nas pedras do riacho, floreiras, troncos de árvores, colunas e postes!",ind:"🎬 Indicado: Enrolados — Disney+"},
    {id:51,type:"multipla",q:"Se você olhar atentamente para as vigas de madeira na praça de Enrolados, qual item icônico que Rapunzel usa para se defender de Flynn Rider você consegue encontrar pendurado?",opts:["Pote de barro","Frigideira de ferro","Seus 21 metros de cabelos mágicos","Pascal"],ans:1,tip:"Rapunzel usa a frigideira de ferro 7 vezes para se defender no filme! Você encontra essas panelas penduradas nas vigas de madeira como easter eggs para os fãs.",ind:null},
    {id:52,type:"multipla",q:"Ao caminhar pelo espaço temático de Enrolados, os cartazes de procurado com o rosto de Flynn Rider têm uma piada visual clássica do filme. O que os guardas do reino nunca conseguem acertar no retrato falado?",opts:["Orelha","Olhos","Boca","Nariz"],ans:3,tip:"Os guardas do reino nunca conseguem desenhar o nariz correto de Flynn Rider nas ilustrações, mantendo a mesma piada hilária do filme.",ind:null},
    {id:53,type:"multipla",q:"Quando o sol se põe e a praça de Enrolados se ilumina, os fotógrafos do Disney PhotoPass oferecem uma foto exclusiva muito disputada. Que foto mágica é essa?",opts:["Uma foto com o cavalo Maximus aparecendo ao seu lado","Uma Magic Shot em que o visitante segura um lampião flutuante real iluminado, igual ao do Festival das Lanternas do filme","Uma imagem noturna com os cabelos dourados da Rapunzel brilhando ao redor do visitante","Um registro em movimento com as flores mágicas de sol desabrochando no chão"],ans:1,tip:"Você consegue tirar uma foto única segurando um lampião flutuante iluminado igual ao do Festival das Lanternas retratado no filme Enrolados. Uma recordação mágica!",ind:null},
    {id:54,type:"multipla",q:"Qual é o valor estimado da construção do banheiro temático da Rapunzel na área Tangled da Fantasyland?",opts:["1 milhão de dólares","3 milhões de dólares","8 milhões de dólares","15 milhões de dólares"],ans:2,tip:"Um banheiro de 8 milhões de dólares — só na Disney isso é possível! É considerado um dos mais bonitos do mundo.",ind:null},
    {id:55,type:"multipla",q:"Qual a utilidade secreta dos troncos de árvore e dos bancos de madeira perto da torre da Rapunzel no espaço de Enrolados?",opts:["Ventiladores de vento e vapor de água","Smellitizers — ventiladores de aromas","Pontos de recarga de celular gratuitos com porta USB e tomadas elétricas embutidas","Caixas de som"],ans:2,tip:"São gratuitos e um verdadeiro salva-vidas para muitos visitantes do parque!",ind:null},
    {id:56,type:"vf",q:"O Mickey's PhilharMagic é um filme em 3D que mistura diversos clássicos da Disney.",ans:true,tip:"Na verdade é uma experiência em 4D! O Mickey's PhilharMagic mistura projeção 3D com efeitos sensoriais como vento, aromas e água. Ótima opção para uma pausa — sem filas grandes e com ar condicionado!",ind:null},
    {id:57,type:"multipla",q:"Ao entrar nos carrinhos da atração The Many Adventures of Winnie the Pooh, que efeito físico real os visitantes sentem na cena em que o vento sopra forte no Bosque dos Cem Acres?",opts:["O carrinho começa a balançar e saltitar para simular o Tigrão pulando","O carrinho simula um movimento de flutuação, deslizando suavemente de um lado para o outro como se estivesse flutuando no vento","Pequenos jatos de água borrifam o rosto dos visitantes","O carrinho gira em 360 graus rapidamente"],ans:1,tip:"O carrinho desliza de um lado para o outro de forma fluida para passar a sensação de que o vento está carregando o pote de mel.",ind:"🎬 Indicado: Ursinho Pooh (2011) e Christopher Robin (2018) — Disney+"},
    {id:58,type:"multipla",q:"A fila de espera do Ursinho Pooh tem atividade nas 'Honey Walls' (Paredes de Mel). O que as crianças fazem nessas telas?",opts:["As crianças usam as mãos para limpar o mel virtual da tela e revelar os personagens escondidos por trás","Os visitantes jogam um videogame de ritmo coletando abelhas virtuais","A tela funciona como um espelho mágico que transforma o reflexo do visitante no Leitão ou no Bisonho","É preciso desenhar um balão vermelho na tela para ajudar o Pooh a flutuar"],ans:0,tip:"As crianças usam as mãos para 'limpar' o mel virtual acumulado na tela, revelando personagens do Bosque dos Cem Acres escondidos por trás.",ind:null},
    {id:59,type:"multipla",q:"Quando a atração Mr. Toad's Wild Ride fechou em 1998, onde os Imagineers esconderam uma homenagem ao Mr. Toad dentro do Winnie the Pooh?",opts:["No livro gigante que se abre no início do passeio","Na sala dos Efalantes e Woozles","Na cena do Blustery Day dentro da casa do Coruja","Na cena em que Pooh fica preso na toca do Coelho"],ans:2,tip:"Preste atenção às paredes quando seu veículo for levado pelo vento para dentro da casa do Coruja. O retrato de Mr. Toad está lá como uma despedida carinhosa!",ind:"🎬 Indicado: As Aventuras de Ichabod e do Sr. Sapo (1949) — Disney+"},
    {id:60,type:"multipla",q:"Qual é a principal novidade da montanha-russa Seven Dwarfs Mine Train, localizada na Fantasyland?",opts:["Um looping duplo de alta velocidade no escuro total","O sistema de carrinhos que balançam de um lado para o outro imitando um vagão de mineração","A queda livre vertical de 40 metros de altura no início do percurso","A opção de pilotar o trem interativamente usando controles de movimento"],ans:1,tip:"O sistema de carrinhos tem um balanço igual aos vagões de mineradoras, pois essa atração acontece na mina de pedras preciosas onde os sete anões trabalham.",ind:"🎬 Indicado: Branca de Neve e os Sete Anões (1937) e Branca de Neve (2025) — Disney+"},
    {id:61,type:"multipla",q:"A fila do Seven Dwarfs Mine Train tem um jogo interativo com barris de água. Quando todos os barris são ativados corretamente, o que aparece no teto da caverna?",opts:["Um arco-íris de luzes brilhantes","A música tema dos Sete Anões começa a tocar","Uma projeção da Branca de Neve dançando com animais surge no teto","O trem dos anões passa correndo"],ans:2,tip:"Quando o jogo dos barris é concluído com sucesso, uma adorável projeção da Branca de Neve aparece no teto da caverna. Uma surpresa que poucos visitantes conseguem ver!",ind:null},
    {id:62,type:"multipla",q:"O restaurante Be Our Guest fica dentro de qual castelo?",opts:["Castelo da Cinderela","Castelo da Bela Adormecida","Castelo da Fera","Castelo do Rei Arthur"],ans:2,tip:"Uma refeição digna de princesa com menu de culinária francesa dividido em 3 alas. A Fera aparece apenas no jantar — planeje se quiser encontrá-la! O Be Our Guest é table-service.",ind:"🎬 Indicado: A Bela e a Fera (1991), live action (2017) — Disney+"},
    {id:63,type:"multipla",q:"Quantas alas existem no restaurante Be Our Guest do Magic Kingdom?",opts:["2 alas — sala principal e galeria","3 alas — sala principal, galeria e ala oeste com a rosa encantada","4 alas — cada uma com um personagem diferente","2 alas — salão de jantar e salão de festas"],ans:1,tip:"A ala oeste é especial — lá fica a famosa rosa encantada do filme! Uma das ambientações mais lindas de todo o Magic Kingdom.",ind:null},
    {id:64,type:"vf",q:"O Cinderella's Royal Table é um restaurante localizado dentro do Castelo da Cinderela onde princesas aparecem para fotos.",ans:true,tip:"Uma das experiências mais especiais do Magic Kingdom — jantar dentro do castelo da Cinderela! É um table-service — reservas abrem com até 60 dias de antecedência para hóspedes Disney.",ind:null},
    {id:65,type:"vf",q:"No restaurante Pinocchio Village Haus existem mesas com janela para a atração It's a Small World.",ans:true,tip:"Uma das experiências mais únicas do parque — você realiza sua refeição enquanto os barquinhos do It's a Small World passam pela janela. O Pinocchio Village Haus é um quick-service.",ind:null},
    {id:66,type:"multipla",q:"Qual é a experiência especial escondida dentro do Pinocchio Village Haus?",opts:["Uma sala secreta com personagens do Pinóquio","O livro dos desejos da Fada Azul — onde você escreve seu sonho e um cast member usa a varinha mágica","Um mini show do Pinóquio que acontece a cada hora","Uma janela secreta para os bastidores do parque"],ans:1,tip:"Ao entrar no salão principal olhe para o lado esquerdo — você verá uma luz azul brilhando ao lado do livro. Leve sua caneta e escreva seu maior sonho. O cast member dirá: Bibbidi Bobbidi Boo!",ind:null},
    {id:67,type:"multipla",q:"Qual é a sobremesa mais famosa do Gaston's Tavern (quick-service) na Fantasyland?",opts:["Torta de maçã da Branca de Neve","Crème Brûlée Croissant — massa leve recheada com creme de baunilha e camada crocante açucarada","Cupcake decorado com a rosa da Bela e a Fera","Wafle de churros no formato do Mickey"],ans:1,tip:"Considerado um dos melhores doces de todo o complexo Disney! Uma versão original do clássico francês em formato de bolinho. Não deixe de provar!",ind:null},
    {id:68,type:"multipla",q:"Qual filme clássico da Disney, lançado em 1941, serve como tema principal e inspiração para a área do Storybook Circus no Magic Kingdom?",opts:["Pinóquio","Peter Pan","Dumbo","A Dama e o Vagabundo"],ans:2,tip:"A área do Storybook Circus é inteiramente inspirada no clássico filme de 1941, Dumbo.",ind:"🎬 Indicado: Dumbo (1941) e a versão live action Dumbo (2019) — Disney+"},
    {id:69,type:"multipla",q:"Qual é o principal objetivo dos visitantes na atividade Smellephants on Parade?",opts:["Encontrar 8 estátuas de elefantes coloridos e adivinhar seus aromas de lanches clássicos do parque","Assistir a um show musical estrelado pelo elefante Dumbo","Colecionar broches exclusivos trocando dicas com os funcionários","Participar de um jogo de tabuleiro gigante nas telas da fila do Dumbo"],ans:0,tip:"Ao completar a caçada mostre para um cast member e ganhe um adesivo especial! Use seu nariz como guia — cada elefante tem um cheiro diferente.",ind:null},
    {id:70,type:"multipla",q:"A montanha-russa infantil do Storybook Circus tem altura mínima de 89cm e velocidade de 40km/h. Qual é o nome dela?",opts:["Dumbo The Flying Elephant","The Barnstormer","Casey Jr. Splash","Pete's Silly Slideshow"],ans:1,tip:"A menor montanha-russa do Magic Kingdom! Perfeita para a primeira vez das crianças em uma montanha-russa de verdade.",ind:null},
    {id:71,type:"multipla",q:"A famosa montanha-russa infantil do Storybook Circus é estrelada por qual personagem da Disney?",opts:["Pato Donald","Pateta como 'The Great Goofini'","Mickey Mouse","Cinderela"],ans:1,tip:"O brinquedo se chama The Barnstormer e é estrelado pelo Pateta em sua versão de acrobata de circo. Um detalhe que a maioria dos visitantes não sabe!",ind:null},
    {id:72,type:"multipla",q:"Na área do Storybook Circus, o que os Imagineers misturaram no cimento do chão antes de secar?",opts:["Moedas de ouro falsas e ingressos rasgados","Amendoins falsos, pegadas de elefantes e marcas de rodas de carruagem de circo","Autógrafos de Walt Disney e animadores originais","Pipocas petrificadas de resina plástica"],ans:1,tip:"Os Imagineers criaram um chão narrativo para que as crianças sintam que as tendas do circo do Dumbo acabaram de ser montadas ali. Uma obra de arte no chão!",ind:null},
    {id:73,type:"multipla",q:"Nas formações rochosas externas do Under the Sea — Journey of the Little Mermaid, qual personagem clássico está esculpido como easter egg?",opts:["Mr. Toad","O Rei Tritão","A Úrsula","O peixe Linguado"],ans:0,tip:"Os Imagineers esculpiram o rosto de Mr. Toad na rocha como homenagem à atração que existia antes. A versão original ainda está na Disneyland da Califórnia!",ind:"🎬 Indicado: A Pequena Sereia (1989) e versão live action (2023) — Disney+"},
    {id:74,type:"multipla",q:"No centro da atração Mad Tea Party há um grande bule de chá. Qual personagem aparece de dentro do bule?",opts:["O Chapeleiro Maluco","O Ratinho dorminhoco (The Dormouse)","O Coelho Branco","O Gato de Cheshire"],ans:1,tip:"O Ratinho dorminhoco é visto saindo de dentro do bule gigante de chá no centro da atração, exatamente como no filme.",ind:"🎬 Indicado: Alice do País das Maravilhas (1951) e Alice no País das Maravilhas (2010) — Disney+"},
    {id:75,type:"multipla",q:"Na atração Enchanted Tales with Belle, em qual cômodo ocorre a peça de teatro interativa onde os convidados ajudam a reencenar a história?",opts:["O Salão de Baile","A Oficina de Maurice","A Biblioteca","A Ala Oeste"],ans:2,tip:"A reencenação da história ocorre na belíssima Biblioteca do castelo, onde os convidados recebem papéis para participar da peça.",ind:"🎬 Indicado: A Bela e a Fera (1991) e live action (2017) — Disney+"},
  ],
  liberty: [
    {id:80,type:"multipla",q:"O que é a Haunted Mansion no Magic Kingdom?",opts:["Um show de terror para maiores de 18 anos","Um passeio em carrinho por um labirinto mal-assombrado","Uma casa de terror onde você caminha pelos ambientes","Um filme 3D de terror da Disney"],ans:1,tip:"Uma das atrações mais queridas e icônicas do Magic Kingdom — tão famosa que está representada em outros parques Disney e nos navios da Disney ao redor do mundo!",ind:"🎬 Indicado: Mansão Mal Assombrada (2023) — Disney+"},
    {id:81,type:"vf",q:"A loja Memento Mori na Liberty Square é considerada a antiga casa de Madame Leota, a médium em espírito que mora na Haunted Mansion.",ans:true,tip:"A loja tem uma história própria dentro do universo da Haunted Mansion. Fique atento aos segredos escondidos por toda ela — tem muito mais do que parece!",ind:null},
    {id:82,type:"vf",q:"Na loja Memento Mori existe um espelho onde Madame Leota aparece algumas vezes.",ans:true,tip:"Fique parado em frente ao espelho por alguns instantes — Madame Leota pode aparecer a qualquer momento. Um momento mágico e assustador ao mesmo tempo!",ind:null},
    {id:83,type:"multipla",q:"O que é o The Hall of Presidents no Magic Kingdom?",opts:["Um museu sobre a história dos Estados Unidos","Um show multimídia com filme histórico e presença de todos os presidentes dos EUA (animatrônicos)","Um encontro com personagens históricos americanos","Uma exposição de fotos dos presidentes americanos"],ans:1,tip:"Uma atração única — cada novo presidente eleito tem seu animatrônico adicionado ao show. Uma combinação fascinante de cinema e teatro ao vivo.",ind:"🎬 Indicado: Hamilton (2020) — Disney+"},
    {id:84,type:"vf",q:"A Ye Old Christmas Shoppe na Liberty Square vende artigos de Natal apenas durante a temporada natalina.",ans:false,tip:"A loja funciona o ano todo! Você encontra bolas decorativas, guirlandas e meias de Natal com os personagens Disney em qualquer época do ano.",ind:null},
    {id:85,type:"multipla",q:"O Country Bear Musical Jamboree é um show com ursos animatrônicos. Qual é a característica especial desses ursos?",opts:["Eles dançam balé clássico","Eles cantam músicas Disney em inglês com sotaque britânico","Eles cantam músicas icônicas da Disney com sotaque especial do Sul dos Estados Unidos","Eles contam histórias do folclore americano sem música"],ans:2,tip:"Um show clássico e muito querido — os ursos têm personalidade própria e o sotaque do Sul americano é parte do charme. Uma atração que encanta gerações desde 1971!",ind:null},
    {id:86,type:"multipla",q:"O Columbia Harbour House (quick-service) na Liberty Square tem algo especial que poucos visitantes conhecem. Qual é?",opts:["Tem um cardápio secreto não listado no menu principal","Possui um andar superior climatizado que frequentemente está mais vazio","Oferece desconto para hóspedes de hotéis Disney","Tem uma janela com vista direta para a Haunted Mansion"],ans:1,tip:"Enquanto todo mundo disputa mesa no térreo, o andar de cima costuma estar bem mais tranquilo — e com ar condicionado! Uma dica de ouro para os dias mais quentes.",ind:null},
    {id:87,type:"multipla",q:"Qual é a sobremesa destaque do Sleepy Hollow (quick-service) na Liberty Square?",opts:["Churros com calda de chocolate","Funnel Cake com frutas vermelhas — morango e mirtilos com chantilly","Waffle de churros no formato do Mickey","Bolo de cenoura com glacê de baunilha"],ans:1,tip:"Considerada uma das sobremesas mais gostosas de todo o Magic Kingdom! O Funnel Cake é uma massa frita aerada e crocante típica americana que você dificilmente encontra no Brasil.",ind:null},
    {id:88,type:"vf",q:"O Liberty Tree Tavern e o The Diamond Horseshoe têm exatamente o mesmo cardápio.",ans:true,tip:"Mesma comida, experiências diferentes! O Liberty Tree Tavern tem atmosfera do século 18 e tende a lotar mais. O Diamond Horseshoe tem temática de velho oeste e costuma estar menos cheio. Ambos são table-service.",ind:null},
    {id:89,type:"multipla",q:"Qual prato típico americano é destaque no Liberty Tree Tavern e no The Diamond Horseshoe?",opts:["Hamburguer artesanal com batatas fritas","Prato de Thanksgiving","Pizza artesanal com ingredientes americanos","Sanduíche de lagosta estilo Nova Inglaterra"],ans:1,tip:"O prato completo de Thanksgiving (Patriot's Platter) é composto por peru assado, purê de batatas e mac and cheese — o famoso macarrão com queijo americano!",ind:null},
    {id:90,type:"multipla",q:"Na Liberty Square, o chão do meio da rua principal tem uma faixa marrom texturizada. O que ela representa historicamente?",opts:["O caminho dos cavalos de carga do século XVIII","O esgoto a céu aberto que corria pelas ruas das cidades americanas antes do encanamento moderno","Uma demarcação de onde as bruxas de Salem foram julgadas","O rastro de lama das carruagens da Revolução Americana"],ans:1,tip:"A Disney preza tanto pelo realismo histórico que imitou o esgoto colonial no chão. Por esse mesmo motivo, a Liberty Square é a única área sem banheiros dentro de seus limites!",ind:null},
    {id:91,type:"multipla",q:"Na Liberty Square as persianas de muitas janelas estão tortas e caídas. Por que isso acontece na história da Disney?",opts:["Os colonos usaram as dobradiças de metal para fazer balas de canhão e as substituíram por tiras de couro que afrouxavam","É um defeito na construção original dos edifícios","Foram danificadas por um furacão e nunca consertadas"],ans:0,tip:"Durante a Revolução Americana, o metal das dobradiças era derretido para armas, deixando os colonos com dobradiças de couro que acabavam cedendo. Realismo histórico incrível!",ind:null},
    {id:92,type:"multipla",q:"A Liberty Square possui uma réplica exata do famoso Sino da Liberdade. De qual cidade americana o sino original vem?",opts:["Boston","Washington D.C.","Filadélfia","Nova Iorque"],ans:2,tip:"O molde original foi usado para criar esta réplica. O Sino da Liberdade original fica na Filadélfia, Pensilvânia, e é um dos símbolos mais importantes da independência americana.",ind:null},
    {id:93,type:"multipla",q:"No Sleepy Hollow (quick-service) na Liberty Square, qual é o lanche em formato de cone feito com massa de waffle?",opts:["Perna de Peru Gigante (Turkey Leg)","Hamburguer de Carne de Cervo","Fresh Fruit Waffle Sandwich ou Chicken Waffle","Clam Chowder"],ans:2,tip:"O Sleepy Hollow é famoso por seus sanduíches gigantes feitos com massa de waffle fresca dobrada ao meio, recheados com frango frito picante ou frutas frescas com Nutella.",ind:null},
  ],
  frontier: [
    {id:100,type:"multipla",q:"Qual é a temática da Big Thunder Mountain no Magic Kingdom?",opts:["Uma corrida de carros antigos","Uma montanha-russa dentro de uma mina de ouro mal-assombrada","Uma viagem pelo Grand Canyon","Uma mina de diamantes encantada"],ans:1,tip:"Uma das montanhas-russas mais clássicas do Magic Kingdom! Estilo familiar, sem looping, com curvas rápidas ao ar livre simulando um trem desgovernado. Perfeita para toda a família.",ind:null},
    {id:101,type:"multipla",q:"Qual é a altura mínima para andar na Big Thunder Mountain?",opts:["89cm","97cm","102cm","112cm"],ans:1,tip:"Com 58km/h e curvas rápidas ao ar livre, a Big Thunder Mountain é classificada como moderada — ideal para crianças que já passaram pelas montanhas-russas mais suaves.",ind:null},
    {id:102,type:"multipla",q:"Existe um truque clássico na Big Thunder Mountain para sentir mais intensidade nas curvas. O que você deve fazer?",opts:["Olhar para o esqueleto de dinossauro","Olhar para o coiote uivando","Manter os olhos fixos no bode com dinamite na boca (Goat Trick)","Fechar os olhos"],ans:2,tip:"Se você mantiver os olhos fixos no bode enquanto o carrinho desce a curva, sua mente sentirá tontura e velocidade muito maior! Esse foco visual engana o ouvido interno e a percepção das forças G.",ind:null},
    {id:103,type:"vf",q:"Um estudo científico publicado na PubMed demonstrou que o passeio na Big Thunder Mountain Railroad pode ajudar a eliminar pequenos cálculos renais — com taxa de sucesso de até 64% sentando nos bancos traseiros.",ans:true,tip:"Pesquisadores testaram um modelo de rim 3D de silicone na atração após relatos de pacientes. O banco de trás teve 64% de taxa de eliminação, contra apenas 17% no banco da frente!",ind:"🔗 pubmed.ncbi.nlm.nih.gov/27669068/"},
    {id:104,type:"multipla",q:"A Big Thunder Mountain é conhecida como 'a corrida mais selvagem do deserto'. Qual é o nome da cidade mineradora fictícia onde a atração se passa?",opts:["Thunder Valley","Tumbleweed","Radiator Springs","Tombstone"],ans:1,tip:"A história conta que a cidade foi abandonada após uma inundação repentina provocada por forças sobrenaturais da montanha. Um detalhe narrativo que poucos visitantes conhecem!",ind:null},
    {id:105,type:"vf",q:"A Tiana's Bayou Adventure substituiu a antiga atração Splash Mountain no Magic Kingdom.",ans:true,tip:"A Splash Mountain foi reformulada e em 2024 se tornou a Tiana's Bayou Adventure — um passeio de barco pelos cenários do filme A Princesa e o Sapo com uma emocionante queda de cachoeira no final!",ind:"🎬 Indicado: A Princesa e o Sapo (2009) — Disney+ · 🎵 Almost There, Down in New Orleans"},
    {id:106,type:"multipla",q:"Qual filme da Disney inspirou a atração Tiana's Bayou Adventure?",opts:["Moana","A Princesa e o Sapo","Enrolados","A Bela e a Fera"],ans:1,tip:"Tiana é a primeira princesa negra da Disney! A atração é inspirada na cidade de Nova Orleans e no bayou — região de pântanos e canais característica do sul dos Estados Unidos.",ind:null},
    {id:107,type:"multipla",q:"Qual é a velocidade da queda principal da Tiana's Bayou Adventure?",opts:["45km/h","55km/h","64km/h","80km/h"],ans:2,tip:"Apesar de ser classificada como splash ride — atração aquática — a queda principal atinge 64km/h! A altura mínima é de 102cm. Prepare-se para se molhar!",ind:null},
    {id:108,type:"multipla",q:"Na atração Tiana's Bayou Adventure, existem quantos vagalumes no total?",opts:["1.999","2.001","2.009","2.039"],ans:2,tip:"Exatamente 2.009 vagalumes — uma referência direta ao ano de lançamento do filme A Princesa e o Sapo (2009)!",ind:null},
    {id:109,type:"multipla",q:"Na fila da Tiana's Bayou Adventure, qual item importante na trama do desenho pode ser visto na cozinha da Tiana?",opts:["O livro de feitiços do Dr. Facilier","A panela de barro original onde ela e seu pai faziam gumbo","O beignet açucarado da Tiana","A Tiara de princesa da Tiana"],ans:1,tip:"Ela fica guardada embaixo da bancada da cozinha — uma referência direta e emocionante ao início do filme.",ind:null},
    {id:110,type:"multipla",q:"Qual é a especialidade gastronômica do Golden Oak Outpost (quick-service) no Frontierland — inspirada na culinária de Nova Orleans?",opts:["Gumbo e arroz cajun","Beignet e limonada de lavanda","Poboy sandwich e sweet tea","Jambalaya e biscuits"],ans:1,tip:"O beignet é um bolinho frito típico de Nova Orleans polvilhado com açúcar de confeiteiro — especialidade da Tiana no filme! A limonada de lavanda é inspirada na influência francesa da gastronomia de Nova Orleans.",ind:null},
  ],
  adventure: [
    {id:115,type:"vf",q:"O Capitão Jack Sparrow faz parte da atração Pirates of the Caribbean desde a sua inauguração.",ans:false,tip:"O Capitão Jack Sparrow foi adicionado à atração apenas depois do enorme sucesso da saga Piratas do Caribe no cinema! A atração original é de 1973 — foi ela que inspirou a criação da franquia.",ind:"🎬 Indicado: Saga Piratas do Caribe — Disney+"},
    {id:116,type:"vf",q:"O Beak and Barrel na Adventureland é o primeiro bar inaugurado dentro do Magic Kingdom.",ans:true,tip:"Por muitos anos o Magic Kingdom não servia bebidas alcoólicas — era uma decisão pessoal de Walt Disney. O Beak and Barrel foi um marco histórico ao inaugurar o primeiro bar do parque!",ind:null},
    {id:117,type:"multipla",q:"Quantos animatrônicos estão presentes na atração Pirates of the Caribbean do Magic Kingdom?",opts:["94","70","126","55"],ans:2,tip:"Um total de 126 Audio-Animatronics — figuras robóticas complexas — entre piratas e animais compõem o cenário da atração.",ind:null},
    {id:118,type:"multipla",q:"Quantos Jack Sparrows estão presentes na atração Pirates of the Caribbean do Magic Kingdom?",opts:["1","2","3","4"],ans:2,tip:"São 3 animatrônicos do Jack Sparrow + 1 projeção em névoa de água logo na primeira caverna escura. Total de 4 aparições do personagem!",ind:null},
    {id:119,type:"vf",q:"A atração Pirates of the Caribbean utiliza a tecnologia Smellitizer em diferentes cenas para intensificar a experiência no ambiente marítimo e pirata.",ans:true,tip:"A atração usa a tecnologia para produzir cheiro de queimado e rum doce em cenas específicas!",ind:null},
    {id:120,type:"vf",q:"O cheiro mais famoso e nostálgico da atração Pirates of the Caribbean — de água úmida, caverna e 'mofo limpo' — não vem de um Smellitizer.",ans:true,tip:"O cheiro mais marcante da atração vem da forma de tratamento da água. A Disney trata os milhões de litros de água com bromo em vez de cloro, gerando aquele aroma marítimo úmido e viciante que os fãs adoram.",ind:null},
    {id:121,type:"multipla",q:"A Pirates Adventure — Treasures of the Seven Seas é uma experiência interativa de caça ao tesouro na Adventureland. Quantas missões ela oferece?",opts:["3 missões","5 missões","7 missões","10 missões"],ans:1,tip:"Você deve ir até o posto de comando (The Crow's Nest), uma pequena cabana entre a atração Pirates of the Caribbean e a área da Frontierland, para receber um mapa. Cada missão dura cerca de 15 a 20 minutos.",ind:null},
    {id:122,type:"vf",q:"Na atração The Magic Carpets of Aladdin quem senta na frente controla a altura do tapete.",ans:true,tip:"Quem senta na frente controla a altura e quem senta atrás controla a inclinação! Uma atração divertida para toda a família — e o encontro com Jasmin e Aladdin acontece nessa mesma área.",ind:"🎬 Indicado: Aladdin (1992) e live action Aladdin (2019) — Disney+"},
    {id:123,type:"vf",q:"No The Magic Carpets of Aladdin existe um camelo que cospe água nos passageiros durante o passeio.",ans:true,tip:"Um dos detalhes mais divertidos e inesperados da atração! O camelo na entrada cospe jatos de água nos passageiros dos tapetes — fique de olho para desviar ou se preparar para se molhar!",ind:null},
    {id:124,type:"multipla",q:"O Jungle Cruise ganha uma versão especial durante o Natal. Qual é o nome dessa versão?",opts:["Christmas Cruise","Holiday Jungle","Jingle Cruise","Santa's Jungle"],ans:2,tip:"Uma das transformações sazonais mais charmosas do Magic Kingdom! O guia continua com as piadas clássicas mas tudo ganha decoração natalina.",ind:"🎬 Indicado: Jungle Cruise (2021) — Disney+"},
    {id:125,type:"vf",q:"A atração Jungle Cruise passa por três regiões de rios tropicais ao redor do mundo.",ans:false,tip:"A atração passa por 4 regiões: rio Mekong (Ásia), rio Congo (África), rio Nilo (África) e rio Amazonas (América do Sul). Dica: a atração realizada à noite possui iluminação especial que faz os animais parecerem muito mais reais!",ind:null},
    {id:126,type:"vf",q:"O Walt Disney's Enchanted Tiki Room é um show agitado com muita ação e efeitos especiais intensos.",ans:false,tip:"O Tiki Room é exatamente o oposto — um show relaxante e contemplativo com pássaros tropicais, flores e estátuas animatrônicas cantando. Perfeito para uma pausa tranquila no meio do dia agitado.",ind:null},
    {id:127,type:"multipla",q:"O Walt Disney's Enchanted Tiki Room tem quatro araras coloridas como mestres de cerimônias. Quais são os nomes desses quatro pássaros?",opts:["José, Michael, Pierre e Fritz","Donald, Zé Carioca, Panchito e Pateta","Iago, Zazu, Flit e Abu"],ans:0,tip:"Cada um representa uma nacionalidade diferente: José é mexicano/espanhol, Michael é irlandês, Pierre é francês e Fritz é alemão. Sotaques divertidíssimos!",ind:null},
    {id:128,type:"multipla",q:"A atração Swiss Family Treehouse é baseada em qual filme da Disney?",opts:["Tarzan","A Família Robinson Suíça de 1960","O Livro da Selva","Peter Pan"],ans:1,tip:"A Swiss Family Treehouse é uma atração walk-through — não tem filas. É um passeio pela enorme casa na árvore construída pelos personagens do filme que naufragaram em uma ilha deserta.",ind:"🎬 Indicado: A família Robinson — Disney+"},
    {id:129,type:"multipla",q:"Qual é o sorvete mais famoso do Aloha Isle (quick-service) na Adventureland?",opts:["Sorvete de chocolate com coco","Dole Whip de abacaxi","Sorvete de manga com maracujá","Milkshake de morango tropical"],ans:1,tip:"O Dole Whip é um dos sorvetes mais famosos e fotografados de todo o Magic Kingdom — disponível nos sabores abacaxi, baunilha ou misto. Uma fila que vale muito a pena enfrentar!",ind:null},
    {id:130,type:"multipla",q:"Qual é o float destaque do Sunshine Tree Terrace (quick-service) na Adventureland?",opts:["Float de morango com Fanta laranja","I Lava You Float — sorvete de laranja com Fanta morango e calda de maracujá vermelho","Float de abacaxi com Sprite e coco","Float de baunilha com Coca-Cola e caramelo"],ans:1,tip:"O nome é uma referência ao curta metragem Lava da Pixar — um vulcão apaixonado! Sorvete de laranja com Fanta morango e calda de maracujá vermelho. Muito refrescante para o calor da Flórida.",ind:"🎬 Indicado: curta Lava — Disney+"},
    {id:131,type:"multipla",q:"Qual é o estilo culinário do Jungle Navigation Co. LTD Skipper Canteen (table-service) na Adventureland?",opts:["Culinária americana clássica","Culinária africana, asiática e latina","Culinária caribenha e mexicana","Culinária francesa e italiana"],ans:1,tip:"Um dos restaurantes mais temáticos e únicos do Magic Kingdom! A temática segue a aventura do Jungle Cruise — você come em um acampamento de exploradores com histórias e piadas na decoração.",ind:null},
  ],
  shows: [
    {id:135,type:"multipla",q:"Qual é o show de fogos de encerramento do Magic Kingdom?",opts:["Disney Enchantment","Happily Ever After","Disney Starlight","Not-So-Spooky Spectacular"],ans:1,tip:"Um show de 18 minutos que acontece na maioria das noites às 22h em frente ao Castelo da Cinderela.",ind:"🎵 Ouça antes: Happily Ever After — Jordan Fisher & Angie Keilhauer"},
    {id:136,type:"vf",q:"O Happily Ever After acontece todas as noites no Magic Kingdom sem exceção.",ans:false,tip:"O show pode ser cancelado por condições climáticas ou eventos especiais. Sempre confirme no app My Disney Experience no dia da visita!",ind:null},
    {id:137,type:"multipla",q:"Qual é a duração da Disney Festival of Fantasy Parade?",opts:["5 minutos","12 minutos","20 minutos","30 minutos"],ans:1,tip:"A parada diurna das 15h traz carros alegóricos grandiosos e personagens clássicos. No inverno veja na praça em frente ao castelo. No verão prefira o Frontier Trading Post — a parada passa mais rápido e você escapa do sol!",ind:null},
    {id:138,type:"vf",q:"A Disney Starlight é uma parada noturna com carros alegóricos iluminados e efeitos especiais tecnológicos.",ans:true,tip:"Acontece geralmente em dois horários — 21h e 23h. Todo iluminado com muita tecnologia e efeitos especiais — completamente diferente da parada diurna. Vale ver as duas para comparar!",ind:null},
    {id:139,type:"multipla",q:"O Mickey's Not-So-Scary Halloween Party tem um show de fogos exclusivo. Qual é o nome?",opts:["Happily Ever After Halloween","Disney's Not-So-Spooky Spectacular","Mickey's Boo-To-You Fireworks","Halloween Enchantment"],ans:1,tip:"Um show de fogos de 12 minutos criado exclusivamente para a festa de Halloween — completamente diferente do Happily Ever After. A festa também tem a Mickey's Boo-To-You Halloween Parade!",ind:"🎬 Indicado: O Estranho Mundo de Jack (1993), Hocus Pocus (1993) e Hocus Pocus 2 (2022) — Disney+"},
    {id:140,type:"vf",q:"O Mickey's Not-So-Scary Halloween Party exige ingresso separado do ingresso normal do parque.",ans:true,tip:"As festas especiais da Disney têm ingresso próprio e separado! O parque fecha para os visitantes regulares e apenas os portadores do ingresso da festa podem entrar — geralmente a partir das 19h.",ind:null},
    {id:141,type:"multipla",q:"O evento Disney After Hours inclui snacks gratuitamente além das filas menores. O que está incluso no ingresso?",opts:["Sorvete do Mickey, pipoca e bebidas engarrafadas liberados e gratuitos","Um jantar completo com as princesas no castelo","Desconto de 50% em todas as lojas do parque","Acesso ilimitado a todas as atrações sem fila"],ans:0,tip:"Carrinhos espalhados pelo parque distribuem esses snacks à vontade durante o evento. Uma vantagem incrível que poucas pessoas sabem!",ind:null},
    {id:142,type:"multipla",q:"Qual é o horário do evento Disney After Hours no Magic Kingdom?",opts:["20h à meia-noite","22h à 1h","21h à meia-noite","23h às 2h"],ans:1,tip:"Com muito menos gente no parque você consegue fazer atrações sem filas enormes! O evento também tem show de fogos exclusivo chamado Disney Enchantment.",ind:null},
    {id:143,type:"vf",q:"O Mickey's Very Merry Christmas Party tem tanto parada temática quanto show de fogos especial de Natal.",ans:true,tip:"A festa natalina tem tudo — Mickey's Once Upon a Christmastime Parade, Minnie's Wonderful Christmastime Fireworks e ainda o Mickey's Most Merriest Celebration no palco do castelo!",ind:"🎬 Indicado: O Conto de Natal de Mickey (1983) — Disney+"},
    {id:144,type:"multipla",q:"Qual é a melhor estratégia para ver a Disney Festival of Fantasy Parade no verão?",opts:["Chegar cedo e ocupar lugar na praça em frente ao castelo","Ver a parada em frente ao Frontier Trading Post — a parada passa mais rápido e você escapa do sol","Assistir de dentro de um restaurante com janela para a rua","Ver do segundo andar do Crystal Palace"],ans:1,tip:"No inverno a praça do castelo é perfeita. No verão o sol forte da Flórida torna aquela área insuportável! No Frontierland a parada passa mais rápido e você fica mais na sombra — uma dica de ouro!",ind:null},
  ],
};
